window.LULU_PASSAGES={"nile": {"src": "qiyas", "text": "تختلف الأنهار فيما بينها اختلافًا كبيرًا من حيث الحجم، فبعضها صغير جدًا حتى إنها تجفّ خلال فصول الجفاف. وأطول نهر في العالم هو نهر النيل في إفريقيا، ويليه من حيث الطول نهر الأمازون في أمريكا الجنوبية، إلا أن كمية المياه التي يحملها نهر الأمازون تفوق كمية المياه في أي نهر آخر، بل وتفوق كمية المياه في نهر النيل، ونهر المسيسيبي في أمريكا، ونهر يانجستي في الصين، مجتمعة.\nوإلى جانب كون الأنهار مهمة للزراعة، فهي مصدر مهم للطاقة؛ إذ يمكن استخدام قوة تدفق المياه على امتداد النهر، عند المساقط وغيرها من المناطق المنحدرة؛ لتشغيل الآلات، وتوليد الكهرباء، حيث تحوّل السواقي والدواليب المائية قوة المياه المتدفقة إلى طاقة. وكانت الطواحين والورش ومصانع النسيج تقام في الماضي بالقرب من الأنهار المنحدرة، وكانت تديرها قوة اندفاع المياه. وفي الوقت الحاضر، تنتج محطات القوة الكهرومائية، ذات التوربينات المائية، نحو ربع القوة الكهربائية التي يحتاجها العالم."}, "brand": {"src": "qiyas", "text": "كلما ترسّخ الاسم التجاري في أذهان الناس؛ زاد استهلاك المنتج؛ وبالتالي زادت أرباح الشركة."}, "knowledge": {"src": "qiyas", "text": "عصرنا عصر انفجار المعرفة؛ فأعداد هائلة من العلماء يشتغلون بالبحث العلمي لاختراع وتطوير وسائل حفظ المعلومات ونقلها وبثّها؛ للدفع قُدُمًا بالتواصل الكوني الفريد. كل ذلك جعل الناس مغمورين بالأخبار والمعلومات والمفاهيم التي ترد إليهم في كل لحظة من شتى أصقاع الأرض."}, "sleep": {"src": "original", "text": "يظن كثير من الطلاب أن السهر حتى الفجر قبل الاختبار يزيد فرص النجاح، لكن الدراسات تشير إلى عكس ذلك؛ ففي أثناء النوم يعيد الدماغ ترتيب المعلومات التي تعلّمها الإنسان في يومه، وينقل المهم منها إلى الذاكرة طويلة المدى. وحين يُحرم الطالب من النوم يقلّ تركيزه، ويبطؤ تفكيره، ويصبح أكثر عُرضة للأخطاء البسيطة. لذلك ينصح المختصون بنوم كافٍ في الليالي التي تسبق الاختبار، وبمراجعة خفيفة بدل الحفظ المتواصل."}, "palm": {"src": "original", "text": "النخلة شجرة مباركة عرفها أهل الجزيرة العربية منذ آلاف السنين، وقد استفادوا من كل جزء فيها: فثمرها غذاء، وجذوعها تُستعمل في تسقيف البيوت، وسعفها يُصنع منه الحصير والسلال، وليفها تُفتل منه الحبال. وتتحمّل النخلة الحرارة الشديدة وقلة الماء، ولهذا انتشرت زراعتها في الواحات. وتُعدّ المملكة العربية السعودية اليوم من أكبر الدول المنتجة للتمور في العالم."}, "bees": {"src": "original", "text": "تعيش النحلة العاملة نحو ستة أسابيع فقط في موسم النشاط، لكنها تقضي هذه المدة القصيرة في عمل متواصل: فهي تنظّف الخلية، وتغذّي اليرقات، وتبني الأقراص الشمعية، ثم تخرج لجمع الرحيق. وتتواصل النحلات فيما بينها برقصات خاصة تدل على مكان الأزهار وبُعدها عن الخلية. والطريف أن النحلة الواحدة لا تنتج طوال حياتها إلا جزءًا صغيرًا من ملعقة عسل؛ فالعسل الذي نأكله ثمرة تعاون آلاف النحلات."}, "khwarizmi": {"src": "original", "text": "يُعدّ محمد بن موسى الخوارزمي من أبرز علماء الرياضيات في الحضارة الإسلامية، عاش في بغداد في القرن الثالث الهجري، وألّف كتاب «المختصر في حساب الجبر والمقابلة» الذي جعل الجبر علمًا مستقلًا. وقد تُرجم الكتاب إلى اللاتينية فانتقل علمه إلى أوروبا، ومن اسمه اشتُقّت كلمة «خوارزمية» التي تُستخدم اليوم في علوم الحاسب للدلالة على خطوات حل المسألة."}, "phone": {"src": "original", "text": "أجرى باحثون تجربة طلبوا فيها من مجموعتين من الطلاب حلّ مسائل ذهنية؛ وُضعت هواتف المجموعة الأولى في غرفة أخرى، بينما بقيت هواتف المجموعة الثانية على الطاولة مقلوبة وصامتة. وجاءت نتائج المجموعة الأولى أفضل، مع أن هواتف المجموعة الثانية لم تُصدر أي إشعار. ويفسّر الباحثون ذلك بأن جزءًا من انتباه الدماغ ينشغل بمقاومة الرغبة في تفقّد الهاتف ما دام قريبًا."}, "desert": {"src": "original", "text": "التصحّر هو تحوّل الأراضي الخصبة تدريجيًا إلى أراضٍ قاحلة، ومن أسبابه الطبيعية قلة الأمطار وارتفاع الحرارة، ومن أسبابه البشرية الرعي الجائر وقطع الأشجار. ولمواجهته تلجأ الدول إلى التشجير، وتنظيم الرعي، وإنشاء مصدّات الرياح. وقد أطلقت المملكة مبادرة «السعودية الخضراء» التي تستهدف زراعة عشرة مليارات شجرة."}};
